        display: inline-block !important;
    }

    /* Show More/Less Button */
    .show-more-btn {
        display: block;
        padding: 4px 12px;
        margin: 10px auto;
        background-color: transparent;
        color: var(--chip-selected-bg);
        border: 1px solid var(--chip-selected-bg);
        border-radius: 10px;
        cursor: pointer;
        user-select: none;
        font-size: 13px;
        transition: all 0.2s ease;
        text-align: center;
        width: fit-content;
    }

    .show-more-btn:hover {
        background-color: rgba(59, 160, 143, 0.1);
    }

    .toggleable-chip {
        display: inline-block;
    }

    .hidden {
        display: none
    }

    /* Responsive Design */
    @media screen and (max-width: 760px) {
        .modal-content {
            box-sizing: border-box;
            width: 90vw;
            margin: 80px auto;
        }

        .custom-btn {
            padding: 6px 8px;
        }

        .filter-icn::after {
            content: "";
        }

        .tips-icn::after {
            content: "";
        }
    }


